import { type ReactNode, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import {
  AlertCircle, ArrowDownRight, ArrowLeft, ArrowUpRight, Banknote, BarChart3, Bell, CalendarDays,
  Check, ChevronRight, CircleDollarSign, Clipboard, Clock3, CreditCard, FileText, LayoutDashboard,
  Menu, MoreHorizontal, Phone, Plus, RefreshCw, Search, Settings2, Share2, ShieldCheck,
  Store, UserPlus, Users, WalletCards, X
} from 'lucide-react';
import {
  CustomerStatusParameter, PaymentMethod,
  getGetContractQueryKey, getGetCustomerQueryKey, getGetExchangeRateQueryKey,
  getGetCreditQueryKey, getGetCustomerStatementQueryKey, getListCustomersQueryKey,
  useCreateCredit, useCreateCustomer, useCreatePayment, useGetContract,
  useGetCustomer, useGetCustomerStatement, useGetDashboardSummary, useGetExchangeRate,
  useGetRecentActivity, useListCustomers, useUpdateExchangeRate,
} from '@workspace/api-client-react';
import type {
  ActivityEvent, Credit, Customer, CustomerDetail, ExchangeRate,
  Payment, PaymentMethod as PaymentMethodType,
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import NotFound from '@/pages/not-found';
import logoUrl from '@assets/photo_2026-09-07_20-52-49_1788828789860.jpg';
import '@/index.css';

const queryClient = new QueryClient();

const money = (value: number | null | undefined, decimals = 2) =>
  new Intl.NumberFormat('es-VE', { style: 'currency', currency: 'USD', minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(value ?? 0);
const bolivar = (value: number | null | undefined) =>
  new Intl.NumberFormat('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value ?? 0);
const date = (value?: string | null, long = false) =>
  value ? new Intl.DateTimeFormat('es-VE', { day: '2-digit', month: long ? 'long' : 'short', year: long ? 'numeric' : undefined }).format(new Date(value)) : 'Sin fecha';
const initials = (name = '') => name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase() || '—';

function cx(...classes: Array<string | false | undefined>) { return classes.filter(Boolean).join(' '); }

function StatusPill({ status }: { status: string }) {
  const labels: Record<string, string> = { current: 'Al día', overdue: 'Vencido', finished: 'Finalizado', active: 'Activo', pending: 'Pendiente', partial: 'Parcial', paid: 'Pagado', signed: 'Firmado' };
  return <span data-testid={`status-${status}`} className={cx('inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold tracking-wide', status === 'overdue' ? 'bg-[#f8d9d0] text-[#a74337]' : status === 'finished' || status === 'paid' || status === 'signed' ? 'bg-[#dcebdd] text-[#277052]' : status === 'partial' ? 'bg-[#f8e8bb] text-[#8c6418]' : 'bg-[#e7eee9] text-[#356d5a]')}>{labels[status] || status}</span>;
}

function PageTitle({ eyebrow, title, children }: { eyebrow: string; title: string; children?: ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
    <div><p className="mb-1 text-[11px] font-bold uppercase tracking-[.18em] text-muted-foreground">{eyebrow}</p><h1 className="font-serif text-3xl font-semibold tracking-[-.03em] text-foreground sm:text-4xl">{title}</h1></div>
    {children}
  </div>;
}

function ErrorState({ label = 'No pudimos cargar estos datos.', onRetry }: { label?: string; onRetry?: () => void }) {
  return <div data-testid="state-error" className="rounded-2xl border border-[#e7beb6] bg-[#fdf0ec] p-6 text-center">
    <AlertCircle className="mx-auto mb-3 h-6 w-6 text-destructive" /><p className="text-sm font-semibold text-[#91443a]">{label}</p><p className="mt-1 text-xs text-[#aa6b61]">Revisa tu conexión e intenta de nuevo.</p>
    {onRetry && <Button data-testid="button-retry" variant="outline" size="sm" className="mt-4 border-[#e7beb6] bg-transparent" onClick={onRetry}><RefreshCw className="mr-2 h-3.5 w-3.5" />Intentar de nuevo</Button>}
  </div>;
}

function EmptyState({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) {
  return <div data-testid="state-empty" className="rounded-2xl border border-dashed border-border bg-card/50 px-6 py-12 text-center">
    <div className="mx-auto mb-4 flex h-11 w-11 items-center justify-center rounded-xl bg-muted text-muted-foreground"><Clipboard className="h-5 w-5" /></div><p className="font-serif text-xl">{title}</p><p className="mx-auto mt-1 max-w-sm text-sm leading-6 text-muted-foreground">{detail}</p>{action && <div className="mt-5">{action}</div>}
  </div>;
}

function LoadingRows({ count = 4 }: { count?: number }) {
  return <div data-testid="state-loading" className="space-y-3">{Array.from({ length: count }).map((_, i) => <div key={i} className="skeleton h-[68px] rounded-xl" />)}</div>;
}

function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const nav = [
    { href: '/', label: 'Resumen', icon: LayoutDashboard },
    { href: '/clientes', label: 'Clientes', icon: Users },
    { href: '/creditos/nuevo', label: 'Nuevo crédito', icon: Plus },
    { href: '/reportes', label: 'Reportes', icon: BarChart3 },
    { href: '/ajustes', label: 'Ajustes', icon: Settings2 },
  ];
  return <div className="grain min-h-[100dvh] bg-background text-foreground">
    <aside className={cx('fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col border-r border-sidebar-border bg-sidebar px-4 py-5 transition-transform duration-300 md:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex items-center justify-between px-3"><Link href="/" data-testid="link-brand" className="flex items-center gap-3"><span className="flex h-11 w-[170px] items-center overflow-hidden rounded-xl bg-[#f1efe9] px-2"><img src={logoUrl} alt="FERRALIA — ECCELLENZA INDUSTRIALE" className="h-full w-full object-cover" /></span></Link><button data-testid="button-close-menu" className="rounded-lg p-2 text-sidebar-foreground/70 md:hidden" onClick={() => setMobileOpen(false)}><X className="h-5 w-5" /></button></div>
      <div className="mt-11 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/40">Mi negocio</div>
      <nav className="mt-3 space-y-1">{nav.map(({ href, label, icon: Icon }) => {
        const active = href === '/' ? location === '/' : location.startsWith(href);
        return <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} className={cx('group flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-medium transition-colors', active ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground')} onClick={() => setMobileOpen(false)}><Icon className={cx('h-[18px] w-[18px]', active ? 'text-sidebar-primary' : 'text-sidebar-foreground/50')} /><span>{label}</span>{active && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-sidebar-primary" />}</Link>;
      })}</nav>
      <div className="mt-auto rounded-2xl border border-sidebar-border bg-sidebar-accent/60 p-4"><div className="mb-3 flex items-center justify-between"><span className="text-[10px] font-bold uppercase tracking-[.15em] text-sidebar-foreground/50">Identidad</span><span className="h-2 w-2 rounded-full bg-sidebar-primary" /></div><p className="font-serif text-base text-sidebar-foreground">ECCELLENZA INDUSTRIALE</p><p className="mt-1 text-xs leading-5 text-sidebar-foreground/55">Precisión y confianza para cada operación.</p></div>
      <div className="mt-5 flex items-center gap-3 border-t border-sidebar-border px-3 pt-5"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-sidebar-primary text-xs font-bold text-sidebar-primary-foreground">FE</div><div className="min-w-0"><p className="truncate text-sm font-semibold text-sidebar-foreground">FERRALIA</p><p className="truncate text-[11px] text-sidebar-foreground/45">Cuenta administradora</p></div><MoreHorizontal className="ml-auto h-4 w-4 text-sidebar-foreground/40" /></div>
    </aside>
    {mobileOpen && <button aria-label="Cerrar menú" data-testid="button-menu-overlay" className="fixed inset-0 z-30 bg-foreground/30 md:hidden" onClick={() => setMobileOpen(false)} />}
    <div className="md:pl-[248px]"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur-md sm:px-8"><button data-testid="button-open-menu" className="rounded-lg p-2 text-muted-foreground md:hidden" onClick={() => setMobileOpen(true)}><Menu className="h-5 w-5" /></button><div className="hidden text-sm text-muted-foreground md:block">Miércoles, <span className="font-semibold text-foreground">{new Intl.DateTimeFormat('es-VE', { day: 'numeric', month: 'long' }).format(new Date())}</span></div><div className="relative ml-auto flex items-center gap-3"><button data-testid="button-notifications" onClick={() => setNotificationsOpen((open) => !open)} className="relative rounded-xl border border-border bg-card p-2.5 text-muted-foreground transition hover:text-foreground"><Bell className="h-4 w-4" /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-accent" /></button>{notificationsOpen && <div data-testid="panel-notifications" className="absolute right-0 top-12 w-64 rounded-2xl border border-border bg-card p-4 shadow-xl"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground">Notificaciones</p><p className="mt-3 text-sm font-semibold">Todo está al día.</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Aquí verás recordatorios de vencimientos y actividad importante.</p><button data-testid="button-close-notifications" onClick={() => setNotificationsOpen(false)} className="mt-3 text-xs font-bold text-primary">Cerrar</button></div>}<div className="hidden h-7 w-px bg-border sm:block" /><span className="hidden text-right sm:block"><strong className="block text-sm">FERRALIA</strong><small className="text-[11px] text-muted-foreground">ECCELLENZA INDUSTRIALE</small></span><div className="flex h-9 w-9 items-center justify-center rounded-full bg-primary text-xs font-bold text-primary-foreground">FE</div></div></header><main className="mx-auto max-w-[1440px] px-5 py-7 sm:px-8 lg:px-10">{children}</main></div>
    <nav className="fixed inset-x-3 bottom-3 z-20 flex items-center justify-around rounded-2xl border border-border bg-card/95 p-2 shadow-lg backdrop-blur-md md:hidden">{nav.slice(0, 4).map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-mobile-${label.toLowerCase().replaceAll(' ', '-')}`} className={cx('flex flex-1 flex-col items-center gap-1 rounded-xl py-2 text-[10px] font-semibold', (href === '/' ? location === '/' : location.startsWith(href)) ? 'bg-primary/10 text-primary' : 'text-muted-foreground')}><Icon className="h-4 w-4" />{label.split(' ')[0]}</Link>)}</nav>
  </div>;
}

function StatCard({ label, value, detail, tone = 'plain', icon: Icon }: { label: string; value: string; detail: string; tone?: 'plain' | 'warm' | 'alert'; icon: typeof WalletCards }) {
  return <div data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`} className={cx('relative overflow-hidden rounded-2xl border p-5 transition-transform hover:-translate-y-0.5', tone === 'warm' ? 'border-[#d8bd79] bg-secondary' : tone === 'alert' ? 'border-[#e7beb6] bg-[#fdf0ec]' : 'border-border bg-card')}><div className="flex items-start justify-between"><p className="text-xs font-semibold uppercase tracking-[.13em] text-muted-foreground">{label}</p><span className={cx('rounded-lg p-2', tone === 'warm' ? 'bg-secondary-foreground/10 text-secondary-foreground' : tone === 'alert' ? 'bg-[#f8d9d0] text-[#a74337]' : 'bg-muted text-primary')}><Icon className="h-4 w-4" /></span></div><p className="number-display mt-5 text-[27px] font-medium text-foreground">{value}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p></div>;
}

function Dashboard() {
  const summary = useGetDashboardSummary();
  const activity = useGetRecentActivity({ limit: 6 });
  const customers = useListCustomers({ status: CustomerStatusParameter.all });
  const [search, setSearch] = useState('');
  const filtered = useMemo(() => (customers.data ?? []).filter((c) => c.fullName.toLowerCase().includes(search.toLowerCase())), [customers.data, search]);
  return <><PageTitle eyebrow="Miércoles · 08:42 a. m." title="Buenos días, Luisa."><div className="flex gap-2"><Link href="/clientes" data-testid="link-all-customers" className="hidden rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-semibold transition hover:border-primary hover:text-primary sm:block">Ver clientes</Link><Link href="/creditos/nuevo" data-testid="link-new-credit" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground shadow-sm transition hover:-translate-y-0.5"><Plus className="h-4 w-4" />Nuevo crédito</Link></div></PageTitle>
    {summary.isError ? <ErrorState onRetry={() => summary.refetch()} /> : summary.isLoading ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{Array.from({ length: 4 }).map((_, i) => <div key={i} className="skeleton h-[152px] rounded-2xl" />)}</div> : <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 animate-rise"><StatCard label="Por cobrar" value={money(summary.data?.totalToCollect)} detail="saldo total pendiente" icon={WalletCards} /><StatCard label="Cobrado este mes" value={money(summary.data?.collectedThisMonth)} detail="pagos recibidos" tone="warm" icon={Banknote} /><StatCard label="En atraso" value={money(summary.data?.overdueAmount)} detail={`${summary.data?.overdueCustomers ?? 0} clientes requieren atención`} tone="alert" icon={Clock3} /><StatCard label="Vence hoy" value={money(summary.data?.dueToday)} detail={`${summary.data?.activeCustomers ?? 0} clientes activos`} icon={CalendarDays} /></div>}
    <div className="mt-8 grid gap-5 xl:grid-cols-[1.15fr_.85fr]">
      <section className="rounded-2xl border border-border bg-card p-5 sm:p-6 animate-rise animate-rise-1"><div className="mb-5 flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Cartera activa</p><h2 className="mt-1 font-serif text-2xl">Tus clientes, de cerca</h2></div><Link href="/clientes" data-testid="link-portfolio" className="text-xs font-bold text-primary hover:underline">Ver todos <ChevronRight className="ml-1 inline h-3 w-3" /></Link></div><div className="relative mb-4"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input data-testid="input-dashboard-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar por nombre..." className="h-10 border-border bg-background pl-9 text-sm" /></div>{customers.isError ? <ErrorState onRetry={() => customers.refetch()} /> : customers.isLoading ? <LoadingRows count={3} /> : filtered.length === 0 ? <EmptyState title="Sin coincidencias" detail={search ? 'Prueba con otro nombre.' : 'Todavía no tienes clientes registrados.'} action={!search ? <Link href="/clientes" data-testid="link-add-first-customer" className="text-sm font-bold text-primary">Registrar un cliente</Link> : undefined} /> : <div className="divide-y divide-border">{filtered.slice(0, 5).map((customer) => <CustomerRow key={customer.id} customer={customer} />)}</div>}</section>
      <section className="rounded-2xl border border-border bg-card p-5 sm:p-6 animate-rise animate-rise-2"><div className="mb-5 flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Movimiento</p><h2 className="mt-1 font-serif text-2xl">Actividad reciente</h2></div><span className="rounded-full bg-muted px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Últimos días</span></div>{activity.isError ? <ErrorState onRetry={() => activity.refetch()} /> : activity.isLoading ? <LoadingRows count={4} /> : !activity.data?.length ? <EmptyState title="Aquí aparecerá tu ritmo" detail="Los cobros y créditos nuevos se verán en esta línea de tiempo." /> : <ActivityList events={activity.data} />}</section>
    </div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[.78fr_1.22fr]"><section className="quiet-grid overflow-hidden rounded-2xl border border-primary/20 bg-primary p-6 text-primary-foreground sm:p-7"><div className="flex items-start justify-between"><ShieldCheck className="h-6 w-6 text-secondary" /><span className="text-[10px] font-bold uppercase tracking-[.16em] text-primary-foreground/55">Tu enfoque</span></div><h2 className="mt-12 max-w-sm font-serif text-3xl leading-tight">Cada pago claro. Cada confianza, más fuerte.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-primary-foreground/65">Mantén el pulso de tu negocio sin perder de vista a las personas que lo hacen posible.</p></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Atención del día</p><h2 className="mt-1 font-serif text-2xl">Lo que pide acción</h2></div><ArrowUpRight className="h-5 w-5 text-accent" /></div><div className="mt-7 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-[#fdf0ec] p-4"><p className="text-xs font-semibold text-[#a74337]">Clientes en atraso</p><p className="number-display mt-2 text-2xl text-[#91443a]">{summary.data?.overdueCustomers ?? '—'}</p><Link href="/clientes?status=overdue" data-testid="link-overdue-customers" className="mt-2 inline-flex text-xs font-bold text-[#a74337]">Revisar cartera <ChevronRight className="ml-1 h-3 w-3" /></Link></div><div className="rounded-xl bg-[#faf3dd] p-4"><p className="text-xs font-semibold text-[#8c6418]">Vencimientos de hoy</p><p className="number-display mt-2 text-2xl text-[#765313]">{money(summary.data?.dueToday)}</p><Link href="/clientes" data-testid="link-today-dues" className="mt-2 inline-flex text-xs font-bold text-[#8c6418]">Ver pendientes <ChevronRight className="ml-1 h-3 w-3" /></Link></div></div></section></div>
  </>;
}

function CustomerRow({ customer }: { customer: Customer }) {
  return <Link href={`/clientes/${customer.id}`} data-testid={`link-customer-${customer.id}`} className="group flex items-center gap-3 py-3.5 transition-colors hover:bg-muted/50"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#dcebdd] text-xs font-bold text-[#277052]">{initials(customer.fullName)}</div><div className="min-w-0 flex-1"><p data-testid={`text-customer-name-${customer.id}`} className="truncate text-sm font-semibold">{customer.fullName}</p><p className="mt-0.5 truncate text-xs text-muted-foreground">{customer.creditsCount} crédito{customer.creditsCount === 1 ? '' : 's'} · {customer.nextDueDate ? `Próximo ${date(customer.nextDueDate)}` : 'Sin vencimientos'}</p></div><div className="text-right"><p className="number-display text-sm font-medium">{money(customer.activeDebt)}</p><StatusPill status={customer.status} /></div><ChevronRight className="h-4 w-4 text-muted-foreground/50 transition-transform group-hover:translate-x-0.5" /></Link>;
}

function ActivityList({ events }: { events: ActivityEvent[] }) {
  return <div className="space-y-1">{events.map((event) => <div key={event.id} data-testid={`activity-${event.id}`} className="flex gap-3 rounded-xl p-2 transition-colors hover:bg-muted/50"><div className={cx('mt-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg', event.type === 'payment' ? 'bg-[#dcebdd] text-[#277052]' : event.type === 'overdue' ? 'bg-[#f8d9d0] text-[#a74337]' : 'bg-[#faf3dd] text-[#8c6418]')}>{event.type === 'payment' ? <Check className="h-4 w-4" /> : event.type === 'overdue' ? <Clock3 className="h-4 w-4" /> : <CreditCard className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{event.title}</p><p className="truncate text-xs text-muted-foreground">{event.description}</p></div><div className="shrink-0 text-right"><p className="number-display text-xs font-medium">{event.amount ? money(event.amount) : ''}</p><p className="mt-1 text-[10px] text-muted-foreground">{date(event.occurredAt)}</p></div></div>)}</div>;
}

function CustomersPage() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [showCreate, setShowCreate] = useState(false);
  const params = { search: search || undefined, status: status as typeof CustomerStatusParameter[keyof typeof CustomerStatusParameter] };
  const customers = useListCustomers(params);
  return <><PageTitle eyebrow="Relación y confianza" title="Clientes"><Button data-testid="button-open-customer-form" className="rounded-xl" onClick={() => setShowCreate(true)}><UserPlus className="mr-2 h-4 w-4" />Nuevo cliente</Button></PageTitle>
    <div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative max-w-lg flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input data-testid="input-customer-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Nombre, cédula o teléfono..." className="h-11 bg-card pl-9" /></div><div className="flex gap-2 overflow-x-auto">{[['all', 'Todos'], ['current', 'Al día'], ['overdue', 'Vencidos'], ['finished', 'Finalizados']].map(([key, label]) => <button key={key} data-testid={`filter-${key}`} onClick={() => setStatus(key)} className={cx('whitespace-nowrap rounded-xl border px-4 text-xs font-bold transition', status === key ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-card text-muted-foreground hover:border-primary/40')}>{label}</button>)}</div></div>
    <div className="rounded-2xl border border-border bg-card p-4 sm:p-6"><div className="mb-4 flex items-center justify-between"><p className="text-xs font-semibold text-muted-foreground">{customers.data?.length ?? 0} registros</p><button data-testid="button-refresh-customers" className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" onClick={() => customers.refetch()}><RefreshCw className="h-4 w-4" /></button></div>{customers.isError ? <ErrorState onRetry={() => customers.refetch()} /> : customers.isLoading ? <LoadingRows count={6} /> : !customers.data?.length ? <EmptyState title={search || status !== 'all' ? 'No hay coincidencias' : 'Empieza tu cartera'} detail={search || status !== 'all' ? 'Prueba con otros filtros o términos de búsqueda.' : 'Registra a tu primer cliente para comenzar a ordenar tus créditos.'} action={<Button data-testid="button-empty-customer" onClick={() => setShowCreate(true)}><UserPlus className="mr-2 h-4 w-4" />Registrar cliente</Button>} /> : <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead><tr className="border-b border-border text-[10px] font-bold uppercase tracking-[.14em] text-muted-foreground"><th className="pb-3 pl-2">Cliente</th><th className="pb-3">Estado</th><th className="pb-3">Créditos</th><th className="pb-3">Próximo pago</th><th className="pb-3 text-right">Saldo</th><th className="w-8 pb-3" /></tr></thead><tbody>{customers.data.map((customer) => <tr key={customer.id} data-testid={`row-customer-${customer.id}`} className="group border-b border-border/70 last:border-0"><td className="py-4 pl-2"><Link href={`/clientes/${customer.id}`} data-testid={`link-customer-record-${customer.id}`} className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#dcebdd] text-xs font-bold text-[#277052]">{initials(customer.fullName)}</div><div><p className="text-sm font-semibold group-hover:text-primary">{customer.fullName}</p><p className="text-xs text-muted-foreground">{customer.idNumber} · {customer.phone}</p></div></Link></td><td><StatusPill status={customer.status} /></td><td className="text-sm">{customer.creditsCount}</td><td className="text-sm text-muted-foreground">{date(customer.nextDueDate, true)}</td><td className="number-display text-right text-sm font-medium">{money(customer.activeDebt)}</td><td><Link href={`/clientes/${customer.id}`} data-testid={`link-open-customer-${customer.id}`}><ChevronRight className="h-4 w-4 text-muted-foreground/50" /></Link></td></tr>)}</tbody></table></div>}</div>
    {showCreate && <CreateCustomerModal onClose={() => setShowCreate(false)} />}
  </>;
}

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/35 p-0 backdrop-blur-[2px] sm:items-center sm:p-4"><div role="dialog" className="max-h-[92dvh] w-full max-w-lg overflow-y-auto rounded-t-3xl border border-border bg-card p-5 shadow-2xl sm:rounded-2xl sm:p-7"><div className="mb-6 flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground">FERRALIA</p><h2 className="mt-1 font-serif text-2xl">{title}</h2></div><button data-testid="button-close-modal" className="rounded-lg p-2 text-muted-foreground hover:bg-muted" onClick={onClose}><X className="h-5 w-5" /></button></div>{children}</div></div>;
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="block"><span className="mb-1.5 block text-xs font-semibold">{label}</span>{children}{hint && <span className="mt-1 block text-[11px] text-muted-foreground">{hint}</span>}</label>; }

function CreateCustomerModal({ onClose }: { onClose: () => void }) {
  const [form, setForm] = useState({ firstName: '', lastName: '', idNumber: '', phone: '', address: '' }); const mutation = useCreateCustomer(); const qc = useQueryClient();
  const submit = (e: React.FormEvent) => { e.preventDefault(); mutation.mutate({ data: form }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListCustomersQueryKey() }); onClose(); } }); };
  return <Modal title="Registrar cliente" onClose={onClose}><form onSubmit={submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre"><Input data-testid="input-first-name" required value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} placeholder="Ej. María" /></Field><Field label="Apellido"><Input data-testid="input-last-name" required value={form.lastName} onChange={(e) => setForm({ ...form, lastName: e.target.value })} placeholder="Ej. González" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Cédula"><Input data-testid="input-id-number" required value={form.idNumber} onChange={(e) => setForm({ ...form, idNumber: e.target.value })} placeholder="V-12.345.678" /></Field><Field label="Teléfono"><Input data-testid="input-phone" required value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="04XX-0000000" /></Field></div><Field label="Dirección"><Input data-testid="input-address" required value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} placeholder="Sector, calle y referencia" /></Field>{mutation.isError && <p data-testid="text-create-error" className="text-xs font-medium text-destructive">No pudimos registrar el cliente. Revisa los datos e intenta de nuevo.</p>}<Button data-testid="button-submit-customer" type="submit" disabled={mutation.isPending} className="mt-2 w-full">{mutation.isPending ? 'Guardando...' : 'Guardar cliente'}</Button></form></Modal>;
}

function CustomerPage() {
  const { id = '' } = useParams<{ id: string }>(); const detail = useGetCustomer(id, { query: { queryKey: getGetCustomerQueryKey(id) } }); const statement = useGetCustomerStatement(id, { query: { queryKey: getGetCustomerStatementQueryKey(id) } }); const [paymentCredit, setPaymentCredit] = useState<Credit | null>(null);
  const share = async () => { if (statement.data?.shareText) await navigator.clipboard?.writeText(statement.data.shareText); };
  if (detail.isLoading) return <LoadingRows count={5} />; if (detail.isError || !detail.data) return <ErrorState label="No encontramos el expediente de este cliente." onRetry={() => detail.refetch()} />;
  const customer = detail.data;
  return <><Link href="/clientes" data-testid="link-back-customers" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground"><ArrowLeft className="h-4 w-4" />Volver a clientes</Link><div className="mb-7 flex flex-col justify-between gap-5 sm:flex-row sm:items-start"><div className="flex items-center gap-4"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[#dcebdd] font-serif text-xl font-semibold text-[#277052]">{initials(customer.fullName)}</div><div><div className="mb-1 flex flex-wrap items-center gap-2"><h1 className="font-serif text-3xl font-semibold">{customer.fullName}</h1><StatusPill status={customer.status} /></div><p className="text-sm text-muted-foreground">{customer.idNumber} · {customer.phone}</p><p className="mt-1 text-xs text-muted-foreground">{customer.address}</p></div></div><div className="flex gap-2"><button data-testid="button-share-statement" onClick={share} className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-3 py-2.5 text-xs font-bold hover:border-primary"><Share2 className="h-4 w-4" />Compartir estado</button><Link href="/creditos/nuevo" data-testid="link-customer-new-credit" className="inline-flex items-center gap-2 rounded-xl bg-primary px-3 py-2.5 text-xs font-bold text-primary-foreground"><Plus className="h-4 w-4" />Nuevo crédito</Link></div></div>
    <div className="grid gap-3 sm:grid-cols-3"><StatCard label="Saldo activo" value={money(customer.activeDebt)} detail="por cobrar" icon={WalletCards} /><StatCard label="A favor" value={money(customer.balanceFavor)} detail="balance disponible" tone="warm" icon={ArrowDownRight} /><StatCard label="Créditos" value={String(customer.creditsCount)} detail="historial total" icon={FileText} /></div>
    <div className="mt-6 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Expediente</p><h2 className="mt-1 font-serif text-2xl">Créditos</h2></div><span className="text-xs text-muted-foreground">{customer.credits.length} registrados</span></div>{!customer.credits.length ? <EmptyState title="Sin créditos todavía" detail="Este cliente no tiene operaciones de crédito registradas." /> : <div className="space-y-3">{customer.credits.map((credit) => <div key={credit.id} data-testid={`card-credit-${credit.id}`} className="rounded-xl border border-border p-4 transition hover:border-primary/40"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{credit.productName}</p><p className="mt-1 text-xs text-muted-foreground">Creado el {date(credit.createdAt, true)} · {credit.installmentCount} cuotas</p></div><StatusPill status={credit.status} /></div><div className="mt-4 grid grid-cols-3 gap-3 border-t border-border pt-3"><div><p className="text-[10px] uppercase tracking-wider text-muted-foreground">Monto</p><p className="number-display mt-1 text-sm">{money(credit.totalAmount)}</p></div><div><p className="text-[10px] uppercase tracking-wider text-muted-foreground">Pagado</p><p className="number-display mt-1 text-sm text-[#277052]">{money(credit.paidAmount)}</p></div><div><p className="text-[10px] uppercase tracking-wider text-muted-foreground">Restante</p><p className="number-display mt-1 text-sm">{money(credit.remainingAmount)}</p></div></div><div className="mt-4 flex items-center justify-between"><Link href={`/contrato/${credit.id}`} data-testid={`link-contract-${credit.id}`} className="text-xs font-bold text-primary">Contrato digital</Link><button data-testid={`button-payment-${credit.id}`} onClick={() => setPaymentCredit(credit)} className="inline-flex items-center gap-1.5 rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground"><Banknote className="h-3.5 w-3.5" />Registrar pago</button></div></div>)}</div>}</section>
      <section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Historial</p><h2 className="mt-1 font-serif text-2xl">Pagos registrados</h2></div><WalletCards className="h-5 w-5 text-secondary-foreground" /></div>{!customer.payments.length ? <EmptyState title="Aún no hay pagos" detail="Los pagos de este cliente aparecerán aquí." /> : <div className="space-y-1">{customer.payments.map((payment) => <PaymentRow key={payment.id} payment={payment} />)}</div>}</section></div>
    {paymentCredit && <PaymentModal credit={paymentCredit} customer={customer} onClose={() => setPaymentCredit(null)} />}
  </>;
}

function PaymentRow({ payment }: { payment: Payment }) { const method: Record<string, string> = { mobile_payment: 'Pago móvil', cash_usd: 'Efectivo USD', zelle: 'Zelle', binance: 'Binance' }; return <div data-testid={`payment-${payment.id}`} className="flex items-center gap-3 rounded-xl p-2.5 hover:bg-muted/50"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#dcebdd] text-[#277052]"><Check className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{method[payment.method] || payment.method}</p><p className="text-xs text-muted-foreground">{date(payment.paidAt, true)}</p></div><div className="text-right"><p className="number-display text-sm font-medium">{money(payment.amountUsd)}</p>{payment.amountBs && <p className="text-[10px] text-muted-foreground">Bs. {bolivar(payment.amountBs)}</p>}</div></div>; }

function PaymentModal({ credit, customer, onClose }: { credit: Credit; customer: CustomerDetail; onClose: () => void }) {
  const [form, setForm] = useState({ method: PaymentMethod.mobile_payment as PaymentMethodType, amountUsd: String(credit.installmentAmount), amountBs: '', exchangeRate: '', note: '' }); const mutation = useCreatePayment(); const rate = useGetExchangeRate(); const qc = useQueryClient();
  const submit = (e: React.FormEvent) => { e.preventDefault(); mutation.mutate({ creditId: credit.id, data: { method: form.method, amountUsd: form.amountUsd ? Number(form.amountUsd) : null, amountBs: form.amountBs ? Number(form.amountBs) : null, exchangeRate: form.amountBs ? Number(form.exchangeRate || rate.data?.value || 0) || null : null, note: form.note || undefined } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetCustomerQueryKey(customer.id) }); qc.invalidateQueries({ queryKey: getGetCustomerStatementQueryKey(customer.id) }); qc.invalidateQueries({ queryKey: getGetCreditQueryKey(credit.id) }); onClose(); } }); };
  return <Modal title="Registrar pago" onClose={onClose}><div className="mb-5 rounded-xl bg-muted p-4"><p className="text-xs text-muted-foreground">{credit.productName}</p><p className="number-display mt-1 text-lg">{money(credit.remainingAmount)} <span className="font-sans text-xs text-muted-foreground">pendiente</span></p></div><form onSubmit={submit} className="space-y-4"><Field label="Método"><select data-testid="select-payment-method" value={form.method} onChange={(e) => setForm({ ...form, method: e.target.value as PaymentMethodType })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="mobile_payment">Pago móvil</option><option value="cash_usd">Efectivo USD</option><option value="zelle">Zelle</option><option value="binance">Binance</option></select></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Monto en USD"><Input data-testid="input-payment-usd" type="number" step="0.01" min="0" required value={form.amountUsd} onChange={(e) => setForm({ ...form, amountUsd: e.target.value })} /></Field><Field label="Monto en bolívares" hint={rate.data?.value ? `Tasa aplicada: Bs. ${bolivar(rate.data.value)} por USD` : 'Opcional'}><Input data-testid="input-payment-bs" type="number" step="0.01" min="0" value={form.amountBs} onChange={(e) => setForm({ ...form, amountBs: e.target.value })} /></Field></div><Field label="Nota" hint="Opcional"><Input data-testid="input-payment-note" value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} placeholder="Referencia o detalle del pago" /></Field>{mutation.isError && <p className="text-xs font-medium text-destructive">No pudimos registrar el pago.</p>}<Button data-testid="button-submit-payment" type="submit" disabled={mutation.isPending} className="w-full">{mutation.isPending ? 'Registrando...' : 'Confirmar pago'}</Button></form></Modal>;
}

function NewCreditPage() {
  const customers = useListCustomers({ status: CustomerStatusParameter.all }); const [form, setForm] = useState({ customerId: '', productName: '', totalAmount: '', downPayment: '0', installmentCount: '4', firstDueDate: '' }); const mutation = useCreateCredit(); const [, setLocation] = useLocation(); const qc = useQueryClient();
  const total = Number(form.totalAmount) || 0; const down = Number(form.downPayment) || 0; const installments = Number(form.installmentCount) || 1; const each = Math.max(0, (total - down) / installments);
  const submit = (e: React.FormEvent) => { e.preventDefault(); mutation.mutate({ data: { customerId: form.customerId, productName: form.productName, totalAmount: total, downPayment: down, installmentCount: installments, firstDueDate: form.firstDueDate } }, { onSuccess: (credit) => { qc.invalidateQueries({ queryKey: getListCustomersQueryKey() }); setLocation(`/clientes/${credit.customerId}`); } }); };
  return <><PageTitle eyebrow="Nueva operación" title="Crear crédito"><Link href="/clientes" data-testid="link-cancel-credit" className="text-sm font-semibold text-muted-foreground hover:text-foreground">Cancelar</Link></PageTitle><div className="grid gap-5 lg:grid-cols-[1fr_360px]"><form onSubmit={submit} className="rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="mb-7"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Paso único</p><h2 className="mt-1 font-serif text-2xl">Los detalles del acuerdo</h2><p className="mt-1 text-sm text-muted-foreground">Define condiciones claras para ambas partes.</p></div><div className="space-y-5"><Field label="Cliente"><select data-testid="select-credit-customer" required value={form.customerId} onChange={(e) => setForm({ ...form, customerId: e.target.value })} className="h-11 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecciona un cliente</option>{customers.data?.map((customer) => <option key={customer.id} value={customer.id}>{customer.fullName} · {customer.idNumber}</option>)}</select>{customers.isError && <span className="mt-1 block text-xs text-destructive">No se pudieron cargar los clientes.</span>}</Field><Field label="Qué está financiando"><Input data-testid="input-product-name" required value={form.productName} onChange={(e) => setForm({ ...form, productName: e.target.value })} placeholder="Ej. Nevera Frigilux 12 pies" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Monto total (USD)"><Input data-testid="input-total-amount" required type="number" min="0.01" step="0.01" value={form.totalAmount} onChange={(e) => setForm({ ...form, totalAmount: e.target.value })} placeholder="0.00" /></Field><Field label="Inicial (USD)"><Input data-testid="input-down-payment" required type="number" min="0" step="0.01" value={form.downPayment} onChange={(e) => setForm({ ...form, downPayment: e.target.value })} /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Número de cuotas"><select data-testid="select-installments" value={form.installmentCount} onChange={(e) => setForm({ ...form, installmentCount: e.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm">{[2, 3, 4, 5, 6, 8, 10, 12, 18, 20].map((n) => <option key={n} value={n}>{n} cuotas</option>)}</select></Field><Field label="Primera fecha de pago"><Input data-testid="input-first-due-date" required type="date" value={form.firstDueDate} onChange={(e) => setForm({ ...form, firstDueDate: e.target.value })} /></Field></div>{mutation.isError && <p data-testid="text-credit-error" className="text-xs font-medium text-destructive">No pudimos crear el crédito. Verifica que todos los datos sean válidos.</p>}<Button data-testid="button-submit-credit" type="submit" disabled={mutation.isPending || customers.isLoading} className="mt-3 w-full sm:w-auto">{mutation.isPending ? 'Creando crédito...' : 'Crear crédito y contrato'}</Button></div></form><aside className="h-fit rounded-2xl border border-[#d8bd79] bg-secondary p-6"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-secondary-foreground/60">Vista previa</p><h2 className="mt-2 font-serif text-2xl text-secondary-foreground">Así quedará el plan</h2><div className="mt-8 space-y-4"><div className="flex justify-between border-b border-secondary-foreground/15 pb-3 text-sm"><span className="text-secondary-foreground/65">Monto financiado</span><strong className="number-display">{money(Math.max(0, total - down))}</strong></div><div className="flex justify-between border-b border-secondary-foreground/15 pb-3 text-sm"><span className="text-secondary-foreground/65">Cada cuota</span><strong className="number-display text-xl">{money(each)}</strong></div><div className="flex justify-between text-sm"><span className="text-secondary-foreground/65">Primera cuota</span><strong>{form.firstDueDate ? date(form.firstDueDate, true) : 'A definir'}</strong></div></div><div className="mt-8 rounded-xl bg-secondary-foreground/10 p-4 text-xs leading-5 text-secondary-foreground/75">El cliente recibirá un contrato digital para revisar y firmar.</div></aside></div></>;
}

function ReportsPage() {
  const summary = useGetDashboardSummary(); const customers = useListCustomers({ status: CustomerStatusParameter.all }); const activity = useGetRecentActivity({ limit: 20 }); const total = summary.data?.totalToCollect ?? 0; const collected = summary.data?.collectedThisMonth ?? 0; const overdue = summary.data?.overdueAmount ?? 0; const health = total + collected ? Math.round((collected / (total + collected)) * 100) : 0;
  return <><PageTitle eyebrow="Lectura del negocio" title="Reportes"><button data-testid="button-export-report" onClick={() => window.print()} className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-semibold"><FileText className="h-4 w-4" />Imprimir reporte</button></PageTitle>{summary.isError ? <ErrorState onRetry={() => summary.refetch()} /> : summary.isLoading ? <LoadingRows count={3} /> : <><div className="grid gap-3 sm:grid-cols-3"><StatCard label="Cobrado este mes" value={money(collected)} detail={`${health}% del flujo registrado`} tone="warm" icon={Banknote} /><StatCard label="Saldo pendiente" value={money(total)} detail="cartera por cobrar" icon={WalletCards} /><StatCard label="Monto en atraso" value={money(overdue)} detail="requiere seguimiento" tone="alert" icon={Clock3} /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Salud de cartera</p><h2 className="mt-1 font-serif text-2xl">Cobranza del mes</h2></div><span className="number-display text-2xl text-primary">{health}%</span></div><div className="mt-8 h-4 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all duration-700" style={{ width: `${health}%` }} /></div><div className="mt-3 flex justify-between text-xs text-muted-foreground"><span>Recibido: {money(collected)}</span><span>Por cobrar: {money(total)}</span></div><div className="mt-10 grid grid-cols-7 items-end gap-2 border-b border-border pb-2 pt-8">{[34, 53, 47, 72, 58, 78, health || 18].map((height, i) => <div key={i} className="group flex flex-col items-center gap-2"><div className={cx('w-full rounded-t-md transition-all hover:opacity-80', i === 6 ? 'bg-secondary' : 'bg-primary/25')} style={{ height: `${height}px` }} /><span className="text-[10px] text-muted-foreground">{['L', 'M', 'M', 'J', 'V', 'S', 'H'][i]}</span></div>)}</div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Distribución</p><h2 className="mt-1 font-serif text-2xl">Cartera</h2></div><Users className="h-5 w-5 text-primary" /></div><div className="mt-7 space-y-5"><ReportBar label="Al día" value={customers.data?.filter((c) => c.status === 'current').length ?? 0} total={customers.data?.length ?? 0} color="bg-primary" /><ReportBar label="En atraso" value={summary.data?.overdueCustomers ?? 0} total={customers.data?.length ?? 0} color="bg-accent" /><ReportBar label="Finalizados" value={customers.data?.filter((c) => c.status === 'finished').length ?? 0} total={customers.data?.length ?? 0} color="bg-secondary" /></div></section></div><section className="mt-5 rounded-2xl border border-border bg-card p-6"><div className="mb-4 flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Trazabilidad</p><h2 className="mt-1 font-serif text-2xl">Actividad del periodo</h2></div><span className="text-xs text-muted-foreground">{activity.data?.length ?? 0} eventos</span></div>{activity.isLoading ? <LoadingRows count={3} /> : activity.isError ? <ErrorState onRetry={() => activity.refetch()} /> : activity.data?.length ? <ActivityList events={activity.data} /> : <EmptyState title="Sin actividad reciente" detail="Cuando cobres o registres créditos, verás el detalle aquí." />}</section></>}</>;
}
function ReportBar({ label, value, total, color }: { label: string; value: number; total: number; color: string }) { const percent = total ? Math.round((value / total) * 100) : 0; return <div><div className="mb-2 flex justify-between text-xs"><span className="font-semibold">{label}</span><span className="text-muted-foreground">{value} · {percent}%</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={cx('h-full rounded-full', color)} style={{ width: `${percent}%` }} /></div></div>; }

function SettingsPage() {
  const rate = useGetExchangeRate(); const update = useUpdateExchangeRate(); const [value, setValue] = useState(''); const [businessNote, setBusinessNote] = useState(''); const qc = useQueryClient();
  const current = rate.data as ExchangeRate | undefined; const submit = (e: React.FormEvent) => { e.preventDefault(); update.mutate({ data: { value: Number(value) } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetExchangeRateQueryKey() }); setValue(''); } }); };
  return <><PageTitle eyebrow="Control del negocio" title="Ajustes"><span className="text-xs text-muted-foreground">Preferencias de FERRALIA</span></PageTitle><div className="grid gap-5 lg:grid-cols-[1fr_.78fr]"><section className="rounded-2xl border border-border bg-card p-6 sm:p-7"><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Conversión diaria</p><h2 className="mt-1 font-serif text-2xl">Tasa BCV</h2><p className="mt-2 max-w-md text-sm leading-6 text-muted-foreground">Usa una referencia única para que cada pago en bolívares tenga el mismo significado.</p></div><div className="rounded-xl bg-secondary p-3 text-secondary-foreground"><CircleDollarSign className="h-5 w-5" /></div></div>{rate.isError ? <div className="mt-7"><ErrorState onRetry={() => rate.refetch()} /></div> : rate.isLoading ? <div className="skeleton mt-7 h-24 rounded-xl" /> : <><div className="mt-7 rounded-xl border border-border bg-muted/50 p-5"><div className="flex items-end justify-between"><div><p className="text-xs text-muted-foreground">Tasa vigente</p><p data-testid="text-current-rate" className="number-display mt-1 text-3xl">{bolivar(current?.value)} <span className="font-sans text-sm text-muted-foreground">Bs. / USD</span></p></div><StatusPill status={current?.source === 'bcv' ? 'signed' : 'current'} /></div><p className="mt-3 text-xs text-muted-foreground">Actualizada {current?.updatedAt ? date(current.updatedAt, true) : 'sin fecha'} · Fuente: {current?.source === 'bcv' ? 'BCV' : 'manual'}</p></div><form onSubmit={submit} className="mt-6 flex flex-col gap-3 sm:flex-row sm:items-end"><Field label="Actualizar manualmente"><Input data-testid="input-exchange-rate" type="number" min="0.01" step="0.01" required value={value} onChange={(e) => setValue(e.target.value)} placeholder={String(current?.value ?? '')} /></Field><Button data-testid="button-update-rate" type="submit" disabled={update.isPending} className="h-10">{update.isPending ? 'Actualizando...' : 'Guardar tasa'}</Button></form>{update.isError && <p className="mt-2 text-xs text-destructive">No pudimos actualizar la tasa.</p>}</>}</section><section className="rounded-2xl border border-border bg-card p-6 sm:p-7"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Tu comercio</p><h2 className="mt-1 font-serif text-2xl">FERRALIA</h2>{businessNote && <p data-testid="text-business-note" className="mt-2 rounded-lg bg-[#faf3dd] px-3 py-2 text-xs text-[#765313]">{businessNote}</p>}<div className="mt-7 space-y-5"><SettingRow icon={Store} label="Nombre comercial" value="FERRALIA" onEdit={() => setBusinessNote('El nombre comercial se encuentra sincronizado con tu cuenta.')} /><SettingRow icon={Phone} label="Teléfono" value="No configurado" onEdit={() => setBusinessNote('Agrega el teléfono desde el perfil administrador cuando esté disponible.')} /><SettingRow icon={ShieldCheck} label="Datos protegidos" value="Cuenta administradora" onEdit={() => setBusinessNote('Tu información se mantiene visible solo para tu negocio.')} /></div><div className="mt-8 rounded-xl bg-muted p-4 text-xs leading-5 text-muted-foreground">Estos datos identifican tu negocio en los contratos y estados de cuenta.</div></section></div></>;
}
function SettingRow({ icon: Icon, label, value, onEdit }: { icon: typeof Store; label: string; value: string; onEdit: () => void }) { return <div className="flex items-center gap-3 border-b border-border pb-4"><div className="rounded-lg bg-muted p-2 text-primary"><Icon className="h-4 w-4" /></div><div className="flex-1"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-0.5 text-sm font-semibold">{value}</p></div><button data-testid={`button-edit-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={onEdit} className="text-xs font-bold text-primary hover:underline">Editar</button></div>; }

function ContractPage() {
  const { creditId = '' } = useParams<{ creditId: string }>(); const contract = useGetContract(creditId, { query: { queryKey: getGetContractQueryKey(creditId) } }); const [accepted, setAccepted] = useState(false);
  if (contract.isLoading) return <div className="mx-auto max-w-lg py-10"><LoadingRows count={3} /></div>; if (contract.isError || !contract.data) return <div className="mx-auto max-w-lg py-10"><ErrorState label="Este contrato todavía no está disponible." onRetry={() => contract.refetch()} /></div>;
  return <div className="mx-auto max-w-lg py-4 sm:py-10"><div className="mb-8 flex items-center justify-center"><img src={logoUrl} alt="FERRALIA — ECCELLENZA INDUSTRIALE" className="h-16 w-64 rounded-xl bg-[#f1efe9] object-cover px-3" /></div><section className="rounded-2xl border border-border bg-card p-6 shadow-sm sm:p-8"><div className="flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.17em] text-muted-foreground">Contrato digital · FERRALIA</p><h1 className="mt-2 font-serif text-3xl">Revisa tu acuerdo</h1></div><StatusPill status={contract.data.status} /></div><div className="mt-8 space-y-5 text-sm leading-6"><p>Este documento resume las condiciones del crédito que tienes con <strong>FERRALIA</strong>. Léelo con calma antes de confirmar.</p><div className="rounded-xl bg-muted p-4"><div className="flex items-start gap-3"><FileText className="mt-1 h-5 w-5 shrink-0 text-primary" /><div><p className="font-semibold">Documento disponible</p><p className="mt-1 text-xs text-muted-foreground">Contrato generado el {date(contract.data.createdAt, true)}.</p><a data-testid="link-view-contract" href={contract.data.url} target="_blank" rel="noreferrer" className="mt-2 inline-block text-xs font-bold text-primary hover:underline">Abrir documento</a></div></div></div><label className="flex cursor-pointer gap-3 rounded-xl border border-border p-4"><input data-testid="checkbox-accept-contract" type="checkbox" checked={accepted} onChange={(e) => setAccepted(e.target.checked)} className="mt-1 h-4 w-4 accent-[hsl(var(--primary))]" /><span className="text-xs leading-5">Confirmo que leí y comprendo las condiciones de este contrato.</span></label><Button data-testid="button-sign-contract" onClick={() => window.open(contract.data.url, '_blank', 'noopener,noreferrer')} disabled={!accepted || contract.data.status === 'signed'} className="w-full">{contract.data.status === 'signed' ? 'Contrato firmado' : 'Abrir para firmar'}</Button><p className="text-center text-[11px] text-muted-foreground">La firma se completa en el documento seguro.</p></div></section><p className="mt-6 text-center text-xs text-muted-foreground">¿Tienes dudas? Comunícate directamente con FERRALIA.</p></div>;
}

function Router() {
  const [location] = useLocation();
  if (location.startsWith('/contrato/')) {
    return <ErrorBoundary resetKey={location}><ContractPage /></ErrorBoundary>;
  }
  return <ErrorBoundary resetKey={location}><Shell><Switch><Route path="/" component={Dashboard} /><Route path="/clientes" component={CustomersPage} /><Route path="/clientes/:id" component={CustomerPage} /><Route path="/creditos/nuevo" component={NewCreditPage} /><Route path="/reportes" component={ReportsPage} /><Route path="/ajustes" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell></ErrorBoundary>;
}

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;